class CityLeaderboard {
  constructor(windowMs) {
    this.windowMs = windowMs;
    this.cities = new Map(); // city -> CityScope
    this.globalHeap = new MinHeap(); // for top-K
  }

  insert(city, driverId, earnings, ts) {
    let scope = this.cities.get(city);
    if (!scope) {
